+
+function labelMinuteToTime(labelMinute: number): string {
+  const hour = Math.floor(labelMinute / 60);
+  const minute = labelMinute % 60;
+
+  return `${hour.toString().padStart(2, "0")}:${minute.toString().padStart(2, "0")}`;
